#!/usr/bin/env python3
"""在独立生成内核中记录 loop 读取与原 SELinux 拒绝，保留返回值。"""
import hashlib
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'scripts'))
import build_lkl_translation_kernel as builder
import lkl_translation_patch
import probe_lkl_translation

builder.OUT = ROOT / 'work/native-linux-nce/loop-read-diagnostic16-kernel-v1'
original_apply = lkl_translation_patch.apply


def apply(source, experiment, guest_page_bytes):
    original_apply(source, experiment, guest_page_bytes)
    loop = source / 'drivers/block/loop.c'
    text = loop.read_text()
    needle = '\t\tlen = vfs_iter_read(lo->lo_backing_file, &i, &pos, 0);'
    assert text.count(needle) == 1
    observed = needle + '''
        if (len < 0) {
            char message[256];
            int size = scnprintf(message, sizeof(message),
                "nce_loop_read_failure comm=%s pid=%d loop=%d pos=%lld bytes=%u result=%ld\\n",
                current->comm, task_pid_nr(current), lo->lo_number,
                (long long)pos, bvec.bv_len, (long)len);
            lkl_ops->print(message, size);
        }'''
    loop.write_text('#include <asm/host_ops.h>\n' + text.replace(needle, observed))
    hooks = source / 'security/selinux/hooks.c'
    text = hooks.read_text()
    needle = '\treturn selinux_revalidate_file_permission(file, mask);'
    assert text.count(needle) == 1
    observed = '''
    int result = selinux_revalidate_file_permission(file, mask);
    if (result < 0 && S_ISBLK(inode->i_mode)) {
        char *subject = NULL, *object = NULL;
        u32 subject_len = 0, object_len = 0;
        int s = security_sid_to_context(sid, &subject, &subject_len);
        int t = security_sid_to_context(isec->sid, &object, &object_len);
        char message[768];
        int size = scnprintf(message, sizeof(message),
            "nce_loop_lsm_failure comm=%s pid=%d path=%s mask=%d result=%d sid=%u isid=%u fsid=%u scontext=%s tcontext=%s\\n",
            current->comm, task_pid_nr(current), file->f_path.dentry->d_name.name,
            mask, result, sid, isec->sid, fsec->sid,
            s ? "unavailable" : subject, t ? "unavailable" : object);
        lkl_ops->print(message, size);
        kfree(subject);
        kfree(object);
    }
    return result;'''
    hooks.write_text('#include <asm/host_ops.h>\n' + text.replace(needle, observed))


lkl_translation_patch.apply = apply
original_build = builder.build


def build(*args, **kwargs):
    out = original_build(*args, **kwargs)
    path = out / 'build.json'
    manifest = json.loads(path.read_text())
    files = [Path(__file__).resolve(), out / 'source/drivers/block/loop.c',
             out / 'source/security/selinux/hooks.c']
    manifest['sha256'].update({str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in files})
    manifest['diagnostic'] = 'Original loop and SELinux file_permission failures observed; return values retained'
    path.write_text(json.dumps(manifest, indent=2) + '\n')
    return out


builder.build = build
probe_lkl_translation.main()
